// Real-terrain contour data, generated by scripts/build-contours.mjs from AWS Terrain Tiles (Mapzen terrarium).
import kilimanjaro from './kilimanjaro.json';
import sajama from './sajama.json';

export type Terrain = typeof kilimanjaro;
export const terrain = { kilimanjaro, sajama } as Record<'kilimanjaro' | 'sajama', Terrain>;
export type TerrainId = keyof typeof terrain;

// Project → terrain sheet (only places with real coordinates in the project data).
export const terrainFor: Record<string, TerrainId> = {
	kilimanjaro: 'kilimanjaro',
	'bolivia-andes': 'sajama',
};

// Coordinates of each page's place, as already used by the expedition map (src/components/ExpeditionMap.astro).
// `fine` = a surveyed summit (shown to the second); otherwise region-level (shown to the minute).
export type Place = { lat: number; lon: number; fine?: boolean };
export const places: Record<string, Place> = {
	kilimanjaro: { lat: kilimanjaro.anchor.lat, lon: kilimanjaro.anchor.lon, fine: true },
	'bolivia-andes': { lat: -18.1, lon: -68.88 },
	'moroccan-sahara': { lat: 31.1, lon: -4.0 },
	'drivers-eye-24h-nurburgring': { lat: 50.33, lon: 6.95 },
	'hotrodtour-cologne-ibiza': { lat: 50.94, lon: 6.96 },
};

const part = (v: number, pos: string, neg: string, fine: boolean, pad: number) => {
	const a = Math.abs(v);
	let d = Math.floor(a);
	let m = Math.floor((a - d) * 60);
	let s = Math.round(((a - d) * 60 - m) * 60);
	if (!fine) {
		m = Math.round((a - d) * 60);
		s = 0;
	}
	if (s === 60) {
		s = 0;
		m++;
	}
	if (m === 60) {
		m = 0;
		d++;
	}
	const dd = String(d).padStart(pad, '0');
	const mm = String(m).padStart(2, '0');
	return fine ? `${dd}°${mm}′${String(s).padStart(2, '0')}″${v < 0 ? neg : pos}` : `${dd}°${mm}′${v < 0 ? neg : pos}`;
};

/** "03°04′33″S" / "037°21′12″E" style survey notation. */
export const dms = (p: Place, lang: 'en' | 'de' = 'en') => ({
	lat: part(p.lat, 'N', 'S', !!p.fine, 2),
	lon: part(p.lon, lang === 'de' ? 'O' : 'E', 'W', !!p.fine, 3),
});
